# g2-strip.py: print a graph JSON response with run-dependent fields removed, for old/new byte comparison.
import json, sys
VOLATILE = {"index_latency_ms", "preselect_latency_ms", "total_latency_ms", "search_latency_ms", "query_latency_ms", "latency_ms", "generated_at"}
def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items() if k not in VOLATILE}
    if isinstance(v, list):
        return [strip(x) for x in v]
    return v
print(json.dumps(strip(json.load(open(sys.argv[1]))), sort_keys=True, indent=1))

